mapper.select:
SELECT notification_id, user_id, category_id, type_code, target_month, threshold_rate, sent_at
FROM notification
WHERE user_id = #{userId}
  AND target_month = #{targetMonth}
ORDER BY sent_at DESC

mapper.delete:
DELETE FROM notification
WHERE user_id = #{userId}
  AND category_id = #{categoryId}
  AND target_month = #{targetMonth}

DELETE FROM notification
WHERE user_id = #{userId}
  AND (
    (type_code = 'BUDGET' AND target_month < #{currentMonth})
        OR (type_code != 'BUDGET' AND sent_at < DATE_SUB(NOW(), INTERVAL 1 MONTH))
    )

mapper.select:
SELECT target_amount
FROM goal
WHERE user_id = #{userId}
  AND category_id = #{categoryId}
  AND `year_month` = #{targetMonth}

SELECT IFNULL(SUM(amount), 0)
FROM `transaction`
WHERE user_id = #{userId}
  AND category_id = #{categoryId}
  AND txn_type = FALSE
  AND DATE_FORMAT(txn_date, '%Y-%m') = #{targetMonth}
